#include <stdio.h>
#include <signal.h>
#include <string.h>

#define CAPACITY 8

volatile sig_atomic_t events[CAPACITY];
volatile sig_atomic_t count = 0, dropped = 0;

void on_signal(int sig) {
    if (count < CAPACITY) events[count++] = sig;
    else dropped++;
}

int signal_of(const char *name) {
    if (strcmp(name, "INT") == 0) return SIGINT;
    if (strcmp(name, "USR1") == 0) return SIGUSR1;
    if (strcmp(name, "USR2") == 0) return SIGUSR2;
    return SIGTERM;
}

const char *name_of(int sig) {
    if (sig == SIGINT) return "INT";
    if (sig == SIGUSR1) return "USR1";
    if (sig == SIGUSR2) return "USR2";
    return "TERM";
}

int main(void) {
    const int all[] = { SIGINT, SIGUSR1, SIGUSR2, SIGTERM };
    for (int i = 0; i < 4; i++) signal(all[i], on_signal);

    int n;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        char cmd[16], name[16] = "";
        scanf("%15s", cmd);
        if (strcmp(cmd, "flush") != 0) scanf("%15s", name);

        if (strcmp(cmd, "raise") == 0) {
            raise(signal_of(name));
        } else if (strcmp(cmd, "ignore") == 0) {
            signal(signal_of(name), SIG_IGN);
        } else if (strcmp(cmd, "listen") == 0) {
            signal(signal_of(name), on_signal);
        } else {
            if (count == 0) printf("(empty)");
            for (int j = 0; j < count; j++) printf("%s%s", j > 0 ? " " : "", name_of(events[j]));
            printf("\n");
            count = 0;
        }
    }
    printf("dropped %d\n", (int)dropped);
    return 0;
}
